def tsp(dist={{dist}}, start={{start}}):
    n = len(dist); INF = float('inf')
    dp = [[INF]*n for _ in range(1<<n)]
    dp[1<<start][start] = 0
    for mask in range(1<<n):
        for u in range(n):
            if dp[mask][u] == INF or not (mask & (1<<u)): continue
            for v in range(n):
                if mask & (1<<v): continue
                nm = mask | (1<<v)
                nd = dp[mask][u] + dist[u][v]
                if nd < dp[nm][v]: dp[nm][v] = nd
    full = (1<<n) - 1
    return min(dp[full][v] + dist[v][start] for v in range(n))
